BookbindingPressStoneMaker.ironStock=12; BookbindingPressStoneMaker.bronzeStock=10; BookbindingPressStoneMaker.woodStock=14; BookbindingPressStoneMaker.leatherStock=8; BookbindingPressStoneMaker.silverStock=8; BookbindingPressStoneMaker.goldStock=6; BookbindingPressStoneMaker.jewelStock=4; BookbindingPressStoneMaker.pearlStock=4
BookbindingPressStoneMaker.productStock = {}; BookbindingPressStoneMaker.buildings = {}; BookbindingPressStoneMaker.maker = nil; BookbindingPressStoneMaker.activeMaking = {}; BookbindingPressStoneMaker.totalProducts = 0; BookbindingPressStoneMaker.dayTimer = 0
function BookbindingPressStoneMaker.init() BookbindingPressStoneMaker.ironStock=12; BookbindingPressStoneMaker.bronzeStock=10; BookbindingPressStoneMaker.woodStock=14; BookbindingPressStoneMaker.leatherStock=8; BookbindingPressStoneMaker.silverStock=8; BookbindingPressStoneMaker.goldStock=6; BookbindingPressStoneMaker.jewelStock=4; BookbindingPressStoneMaker.pearlStock=4; BookbindingPressStoneMaker.productStock={}; BookbindingPressStoneMaker.buildings={}; BookbindingPressStoneMaker.maker=nil; BookbindingPressStoneMaker.activeMaking={}; BookbindingPressStoneMaker.totalProducts=0; BookbindingPressStoneMaker.dayTimer=0; print("[BookbindingPressStoneMaker] Royal Bookbinding Press Stone Maker System initialized (6 products, 4 buildings)") end
function BookbindingPressStoneMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookbindingPressStoneMaker.maker={name=n or ("Kamnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kamnar najet: %s (spretnost: %d)",BookbindingPressStoneMaker.maker.name,s),"success") end; return true end
function BookbindingPressStoneMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookbindingPressStoneMaker.build(id) local ok,e=BookbindingPressStoneMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookbindingPressStoneMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookbindingPressStoneMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookbindingPressStoneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookbindingPressStoneMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookbindingPressStoneMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookbindingPressStoneMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookbindingPressStoneMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookbindingPressStoneMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookbindingPressStoneMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookbindingPressStoneMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookbindingPressStoneMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookbindingPressStoneMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookbindingPressStoneMaker.buildings==0 then return false,"Potrebna kamnarska delavnica" end; if not BookbindingPressStoneMaker.maker then return false,"Potreben kamnar" end; return true end
function BookbindingPressStoneMaker.make(pt,qty) qty=qty or 1; local ok,e=BookbindingPressStoneMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookbindingPressStoneMaker.ironStock=BookbindingPressStoneMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookbindingPressStoneMaker.bronzeStock=BookbindingPressStoneMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookbindingPressStoneMaker.woodStock=BookbindingPressStoneMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookbindingPressStoneMaker.leatherStock=BookbindingPressStoneMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookbindingPressStoneMaker.silverStock=BookbindingPressStoneMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookbindingPressStoneMaker.goldStock=BookbindingPressStoneMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookbindingPressStoneMaker.jewelStock=BookbindingPressStoneMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookbindingPressStoneMaker.pearlStock=BookbindingPressStoneMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookbindingPressStoneMaker.maker then t=math.max(1,t-math.floor(BookbindingPressStoneMaker.maker.skill/13)) end; table.insert(BookbindingPressStoneMaker.activeMaking,{id="bookbindingpressstone_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookbindingPressStoneMaker.completeMaking(m) local q=1.0+(BookbindingPressStoneMaker.getQualityBonus()/100); if BookbindingPressStoneMaker.maker then q=q+(BookbindingPressStoneMaker.maker.skill/140) end; q=math.min(2.5,q); BookbindingPressStoneMaker.productStock[m.productType]=(BookbindingPressStoneMaker.productStock[m.productType] or 0)+m.quantity; BookbindingPressStoneMaker.totalProducts=BookbindingPressStoneMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookbindingPressStoneMaker.maker then BookbindingPressStoneMaker.maker.itemsMade=BookbindingPressStoneMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookbindingPressStoneMaker.maker.skill=math.min(100,BookbindingPressStoneMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kamen izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookbindingpressstone.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookbindingPressStoneMaker.update(dt) if not _G.state then return end; BookbindingPressStoneMaker.dayTimer=BookbindingPressStoneMaker.dayTimer+dt; if BookbindingPressStoneMaker.dayTimer>=30 then BookbindingPressStoneMaker.dayTimer=0; for i=#BookbindingPressStoneMaker.activeMaking,1,-1 do local m=BookbindingPressStoneMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookbindingPressStoneMaker.completeMaking(m); table.remove(BookbindingPressStoneMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookbindingPressStoneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookbindingPressStoneMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookbindingPressStoneMaker.getStats() return {ironStock=BookbindingPressStoneMaker.ironStock,bronzeStock=BookbindingPressStoneMaker.bronzeStock,woodStock=BookbindingPressStoneMaker.woodStock,leatherStock=BookbindingPressStoneMaker.leatherStock,silverStock=BookbindingPressStoneMaker.silverStock,goldStock=BookbindingPressStoneMaker.goldStock,jewelStock=BookbindingPressStoneMaker.jewelStock,pearlStock=BookbindingPressStoneMaker.pearlStock,productStock=BookbindingPressStoneMaker.productStock,numBuildings=#BookbindingPressStoneMaker.buildings,hasMaker=BookbindingPressStoneMaker.maker~=nil,makerName=BookbindingPressStoneMaker.maker and BookbindingPressStoneMaker.maker.name or "—",makerSkill=BookbindingPressStoneMaker.maker and BookbindingPressStoneMaker.maker.skill or 0,activeMaking=#BookbindingPressStoneMaker.activeMaking,totalProducts=BookbindingPressStoneMaker.totalProducts} end
return BookbindingPressStoneMaker
